tool_calls.text:
/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
/**
 * Build the checkout request the storefront POSTs to "'`cart/<cartCode>/checkout`.
 *
 * Body field names follow the backend order request classes
 * (PersistableOrder / PersistableAnonymousOrder from com.salesmanager.shop.model.order.v1)
 * and its PersistablePayment class:
 *   - chosen shipping option -> quoteId
 *   - currency               -> currency
 *   - terms accepted         -> termsAccepted
 *   - order comment          -> orderNote
 *   - payment object         -> payment { paymentType, transactionType, processor, cardToken, amount }
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: "POST",
    path: "cart/" + cartCode + "/checkout",
    body: {
      quoteId: shippingOptionId,
      currency: currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: "CREDITCARD",
        transactionType: "CAPTURE",
        processor: paymentModule,
        cardToken: paymentToken,
        amount: amount,
      },
    },
  };
}
EOF
node --check src/util/checkoutRequest.mjs && echo SYNTAX_OK'
